package httpserver

import "html/template"

var dashboardTemplates = template.Must(template.New("dashboard").Funcs(template.FuncMap{
	"categoryLabel": dashboardCategoryLabel,
	"deviceName":    dashboardDeviceName,
}).Parse(`
{{define "setup"}}<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>初始化 · DComic 同步</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body class="login-page"><main class="login-card setup-card"><p class="eyebrow">首次使用</p><h1>创建 root 管理员</h1><p class="muted">请输入服务器启动日志中的初始化码。该码仅在当前服务器进程运行期间有效。</p>{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<form method="post" action="/dashboard/setup"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>用户名<input value="root" readonly aria-readonly="true"></label><label>初始化码<input name="initializationCode" autocomplete="off" autocapitalize="none" spellcheck="false" required autofocus></label><label>密码<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required><span class="field-help">长度须为 12–72 个 UTF-8 字节。</span></label><label>确认密码<input type="password" name="confirmPassword" minlength="12" maxlength="72" autocomplete="new-password" required></label><button type="submit">创建 root 账户</button></form><p class="setup-footnote">初始化完成后，此数据库将永久关闭初始化入口。</p></main></body></html>{{end}}
{{define "login"}}<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>登录 · DComic 同步</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body class="login-page"><main class="login-card"><h1>DComic 同步</h1><p class="muted">服务器管理后台</p>{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<form method="post" action="/dashboard/login"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>用户名<input name="username" autocomplete="username" required autofocus></label><label>密码<input type="password" name="password" autocomplete="current-password" required></label><button type="submit">登录</button></form></main></body></html>{{end}}
{{define "overview"}}<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>管理后台 · DComic 同步</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body><header><a class="brand" href="/dashboard">DComic 同步</a><div><span>{{.Admin.Username}}</span><form class="inline" method="post" action="/dashboard/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="link" type="submit">退出登录</button></form></div></header><main><div class="title"><div><h1>概览</h1><p class="muted">账户及已保存的同步数据</p></div></div>{{if .Notice}}<div class="notice">{{.Notice}}</div>{{end}}{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<section class="stats"><article><strong>{{.Stats.Users}}</strong><span>用户数</span></article><article><strong>{{.Stats.Enabled}}</strong><span>已启用用户</span></article><article><strong>{{.Stats.Devices}}</strong><span>有效设备</span></article><article><a href="#users"><strong>{{.Stats.Records}}</strong><span>同步记录</span></a></article><article><a href="#users"><strong>{{.Stats.Conflicts}}</strong><span>待处理冲突</span></a></article></section><section class="panel"><h2>创建用户</h2><form class="create-grid" method="post" action="/dashboard/users"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>用户名<input name="username" minlength="3" maxlength="64" required></label><label>初始密码<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><button type="submit">创建</button></form></section><section class="panel" id="users"><h2>用户列表</h2><div class="table-wrap"><table><thead><tr><th>用户</th><th>状态</th><th>设备</th><th>同步记录</th><th>冲突</th><th>同步游标</th></tr></thead><tbody>{{range .Users}}<tr><td><a href="/dashboard/users/{{.ID}}"><strong>{{.Username}}</strong></a>{{if .Admin}} <span class="tag">管理员</span>{{end}}</td><td>{{if .Disabled}}<span class="bad">已禁用</span>{{else}}<span class="good">已启用</span>{{end}}</td><td>{{.DeviceCount}}</td><td><a href="/dashboard/users/{{.ID}}/sync">{{.RecordCount}}</a></td><td><a href="/dashboard/users/{{.ID}}#conflicts">{{.ConflictCount}}</a></td><td>{{.LatestCursor}}</td></tr>{{else}}<tr><td colspan="6">暂无用户。</td></tr>{{end}}</tbody></table></div></section></main></body></html>{{end}}
{{define "user"}}<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>用户详情 · {{.User.Username}} · DComic 同步</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body><header><a class="brand" href="/dashboard">DComic 同步</a><span>{{.Admin.Username}}</span></header><main><p><a href="/dashboard">← 返回概览</a></p><div class="title"><div><h1>{{.User.Username}}</h1><p class="muted">创建时间：{{.User.CreatedAt.Format "2006-01-02 15:04 UTC"}}</p></div>{{if .User.Disabled}}<form method="post" action="/dashboard/users/{{.User.ID}}/enable"><input type="hidden" name="csrf" value="{{.CSRF}}"><button type="submit">启用账户</button></form>{{else}}<form method="post" action="/dashboard/users/{{.User.ID}}/disable"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="danger" type="submit">禁用账户</button></form>{{end}}</div>{{if .Notice}}<div class="notice">{{.Notice}}</div>{{end}}{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<section class="stats"><article><strong>{{.User.DeviceCount}}</strong><span>有效设备</span></article><article><a href="/dashboard/users/{{.User.ID}}/sync"><strong>{{.User.RecordCount}}</strong><span>同步记录</span></a></article><article><a href="#conflicts"><strong>{{.User.ConflictCount}}</strong><span>待处理冲突</span></a></article><article><a href="/dashboard/users/{{.User.ID}}/sync"><strong>{{.User.LatestCursor}}</strong><span>最新同步游标</span></a></article></section><section class="panel"><h2>重置密码</h2><p class="muted">重置后将立即撤销此用户的所有设备和后台登录会话。</p><form class="create-grid" method="post" action="/dashboard/users/{{.User.ID}}/password"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>新密码<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><button class="danger" type="submit">重置密码并撤销会话</button></form></section><section class="panel"><h2>设备列表</h2><div class="table-wrap"><table><thead><tr><th>名称</th><th>设备 ID</th><th>最近在线（UTC）</th><th>到期日期（UTC）</th><th>状态</th><th></th></tr></thead><tbody>{{range .Devices}}<tr><td>{{deviceName .Name .DeviceID}}</td><td><code>{{.DeviceID}}</code></td><td>{{.LastSeen.Format "2006-01-02 15:04"}}</td><td>{{.ExpiresAt.Format "2006-01-02"}}</td><td>{{if .Revoked}}已撤销{{else}}未撤销{{end}}</td><td>{{if not .Revoked}}<form method="post" action="/dashboard/users/{{$.User.ID}}/devices/{{.ID}}/revoke"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="small danger" type="submit">撤销会话</button></form>{{end}}</td></tr>{{else}}<tr><td colspan="6">暂无设备。</td></tr>{{end}}</tbody></table></div></section>
<section class="panel" id="conflicts"><div class="section-title"><div><h2>同步冲突</h2><p class="muted">选择最终保留并同步到各设备的版本。</p></div><a href="/dashboard/users/{{.User.ID}}/sync">查看同步详情</a></div>
{{range .Conflicts}}<article class="conflict"><h3><code>{{categoryLabel .Candidate.Category}} / {{.Candidate.Key}}</code></h3><div class="conflict-grid">
<section><h4>候选版本</h4><p class="metadata">{{.Candidate.DeviceName}} · <code>{{.Candidate.DeviceID}}</code><br>HLC 版本：{{.Candidate.Version.Wall}}:{{.Candidate.Version.Logical}}</p><details><summary>{{if .Candidate.Deleted}}删除标记{{else if .Candidate.Redacted}}敏感内容已隐藏{{else}}展开内容{{end}}</summary><pre>{{.Candidate.Value}}</pre></details><form method="post" action="/dashboard/users/{{$.User.ID}}/conflicts/{{.ID}}/resolve"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="choice" value="candidate"><input type="hidden" name="expectedWall" value="{{.ExpectedWall}}"><input type="hidden" name="expectedLogical" value="{{.ExpectedLogical}}"><input type="hidden" name="expectedDevice" value="{{.ExpectedDevice}}"><button type="submit">保留候选版本</button></form></section>
<section><h4>服务器当前版本</h4><p class="metadata">{{.Current.DeviceName}} · <code>{{.Current.DeviceID}}</code><br>HLC 版本：{{.Current.Version.Wall}}:{{.Current.Version.Logical}}</p><details><summary>{{if .Current.Deleted}}删除标记{{else if .Current.Redacted}}敏感内容已隐藏{{else}}展开内容{{end}}</summary><pre>{{.Current.Value}}</pre></details><form method="post" action="/dashboard/users/{{$.User.ID}}/conflicts/{{.ID}}/resolve"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="choice" value="server"><input type="hidden" name="expectedWall" value="{{.ExpectedWall}}"><input type="hidden" name="expectedLogical" value="{{.ExpectedLogical}}"><input type="hidden" name="expectedDevice" value="{{.ExpectedDevice}}"><button type="submit">保留服务器版本</button></form></section>
</div></article>{{else}}<p>暂无待处理冲突。</p>{{end}}</section>
<section class="panel"><h2>同步状态</h2><p>已保存记录：<a href="/dashboard/users/{{.User.ID}}/sync"><strong>{{.User.RecordCount}}</strong></a> · 待处理冲突：<a href="#conflicts"><strong>{{.User.ConflictCount}}</strong></a> · 最新同步游标：<strong>{{.User.LatestCursor}}</strong></p><p class="muted">管理后台不显示令牌与 Cookie 的内容。</p></section></main></body></html>{{end}}
{{define "sync-details"}}<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>同步详情 · {{.User.Username}} · DComic 同步</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body><header><a class="brand" href="/dashboard">DComic 同步</a><span>{{.Admin.Username}}</span></header><main><p><a href="/dashboard/users/{{.User.ID}}">← 返回用户 {{.User.Username}}</a></p><div class="title"><div><h1>同步详情</h1><p class="muted">已接收的变更按最新优先排列，服务器接收时间与 HLC 版本分别显示。</p></div></div>
<nav class="category-filter" aria-label="同步类别"><a class="{{if not .Category}}active{{end}}" href="/dashboard/users/{{.User.ID}}/sync">全部</a>{{range .Categories}}<a class="{{if eq $.Category .Category}}active{{end}}" href="/dashboard/users/{{$.User.ID}}/sync?category={{.Category}}">{{categoryLabel .Category}} <span>{{.Records}} 条记录 · {{.Deleted}} 条已删除 · {{.Conflicts}} 个冲突</span></a>{{end}}</nav>
<section class="panel"><h2>{{if .Category}}{{categoryLabel .Category}}{{else}}全部类别{{end}}的变更</h2><p class="muted">当前记录 {{.Stats.Records}} 条（含删除标记）· 已删除 {{.Stats.Deleted}} 条 · 待处理冲突 {{.Stats.Conflicts}} 个</p>{{range .Changes}}<article class="change"><h3><code>{{categoryLabel .Category}} / {{.Key}}</code></h3><p class="metadata">变更序号 #{{.Sequence}} · 来源设备：{{.DeviceName}} · <code>{{.DeviceID}}</code><br>服务器接收时间：{{.ReceivedAt.Format "2006-01-02 15:04:05 UTC"}} · HLC 版本：{{.Version.Wall}}:{{.Version.Logical}}</p><details><summary>{{if .Deleted}}删除标记{{else if .Redacted}}敏感内容已隐藏{{else}}展开同步内容{{end}}</summary><pre>{{.Value}}</pre></details></article>{{else}}<p>此类别暂无已接收的变更。</p>{{end}}{{if .NextURL}}<p class="pagination"><a href="{{.NextURL}}">更早的变更 →</a></p>{{end}}</section>
{{if .Conflicts}}<section class="panel" id="conflicts"><h2>待处理冲突</h2><p>请前往<a href="/dashboard/users/{{.User.ID}}#conflicts">用户 {{.User.Username}} 的详情页</a>处理冲突。</p>{{range .Conflicts}}<p><code>{{categoryLabel .Candidate.Category}} / {{.Candidate.Key}}</code> — {{.Candidate.DeviceName}} 与 {{.Current.DeviceName}}</p>{{end}}</section>{{end}}</main></body></html>{{end}}
`))

const dashboardCSS = `:root{color-scheme:light;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;background:#f5f7fb;color:#172033}*{box-sizing:border-box}body{margin:0}a{color:#275bd8;text-decoration:none}a:hover{text-decoration:underline}header{height:64px;padding:0 max(20px,calc((100vw - 1160px)/2));display:flex;align-items:center;justify-content:space-between;background:#111a2e;color:#fff;gap:20px}.brand{font-size:1.15rem;font-weight:750;color:#fff}main{max-width:1160px;margin:0 auto;padding:28px 20px 60px}.title{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}h1{margin:0 0 4px;font-size:clamp(1.7rem,4vw,2.3rem)}h2{margin:0 0 18px;font-size:1.15rem}.muted{color:#69758b;margin:.35rem 0 1rem}.stats{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:14px;margin-bottom:22px}.stats article,.panel,.login-card{background:#fff;border:1px solid #e1e6ef;border-radius:12px;box-shadow:0 3px 14px rgba(17,26,46,.05)}.stats article{padding:18px}.stats strong{display:block;font-size:1.75rem}.stats span{color:#69758b;font-size:.87rem}.panel{padding:22px;margin-bottom:22px}.create-grid{display:grid;grid-template-columns:1fr 1.5fr auto;gap:14px;align-items:end}label{display:grid;gap:7px;font-size:.87rem;font-weight:650}input{width:100%;padding:10px 12px;border:1px solid #bac3d2;border-radius:8px;font:inherit;background:#fff}input:focus{outline:3px solid #d8e3ff;border-color:#275bd8}button{border:0;border-radius:8px;background:#275bd8;color:#fff;font:inherit;font-weight:700;padding:10px 16px;cursor:pointer}button:hover{filter:brightness(.93)}button.danger{background:#b52832}.small{padding:7px 10px;font-size:.82rem}.inline{display:inline}.link{background:transparent;padding:6px 8px;color:#bcd0ff}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:680px}th,td{text-align:left;padding:12px;border-bottom:1px solid #e7eaf0;font-size:.9rem}th{color:#69758b;font-size:.78rem;text-transform:uppercase;letter-spacing:.04em}.tag{background:#e5ecff;color:#214da8;border-radius:99px;padding:3px 7px;font-size:.7rem}.good{color:#167044}.bad{color:#aa2630}.notice,.alert{padding:12px 14px;border-radius:8px;margin:0 0 18px}.notice{background:#e5f5ec;color:#12623b}.alert{background:#fde8ea;color:#8d2029}.login-page{min-height:100vh;display:grid;place-items:center;padding:20px;background:linear-gradient(145deg,#101a31,#274b91)}.login-card{width:min(420px,100%);padding:32px}.login-card form{display:grid;gap:18px}.login-card button{margin-top:4px}code{font-size:.82rem}@media(max-width:800px){.stats{grid-template-columns:repeat(2,1fr)}.create-grid{grid-template-columns:1fr}.title{align-items:flex-start;flex-direction:column}header{height:auto;padding-top:14px;padding-bottom:14px}}@media(max-width:420px){main{padding-left:14px;padding-right:14px}.stats{grid-template-columns:1fr 1fr}.panel{padding:16px}}`

const dashboardSyncCSS = `.section-title{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.conflict{border-top:1px solid #e7eaf0;padding:18px 0}.conflict:first-of-type{border-top:0;padding-top:0}.conflict-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.conflict-grid>section{border:1px solid #e1e6ef;border-radius:9px;padding:16px}.conflict-grid form{margin-top:14px}.metadata{color:#69758b;font-size:.86rem;line-height:1.55}.category-filter{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:22px}.category-filter a{display:grid;background:#fff;border:1px solid #d5dbe6;border-radius:9px;padding:9px 12px}.category-filter a.active{border-color:#275bd8;background:#edf2ff}.category-filter span{color:#69758b;font-size:.75rem}.change{border-top:1px solid #e7eaf0;padding:16px 0}.change:first-of-type{border-top:0;padding-top:0}details{margin:.65rem 0}summary{color:#275bd8;cursor:pointer;font-weight:650}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f5f7fb;border-radius:8px;padding:13px;font-size:.82rem}.pagination{text-align:right;margin-bottom:0}@media(max-width:700px){.conflict-grid{grid-template-columns:1fr}.section-title{display:block}}`
